from pathlib import Path
import json, html

R=Path(__file__).resolve().parents[1]
D=R/'dist'
gallery=json.loads((R/'source/gallery.json').read_text())
assets=json.loads((R/'source/asset-map.json').read_text())
qa=json.loads((R/'source/qa.json').read_text())
MAIN='0y14chldcipxr.js'
def ref(line,label='Код оригинала',file=MAIN):
    return f'<p class="ref">Источник: <a href="/source-view.html?file={file}&line={line}">{label} · {file}:{line}</a>.</p>'
def pic(n,caption=None):
    x=gallery[n-1]
    return f'<figure><a href="/{x["file"]}"><img loading="lazy" src="/{x["file"]}" alt="{html.escape(caption or x["label"])}"></a><figcaption>{html.escape(caption or x["label"])}</figcaption></figure>'
def table(head,rows):
    return '<div class="table-wrap"><table><thead><tr>'+''.join(f'<th>{x}</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def code(s):return '<pre><code>'+html.escape(s.strip())+'</code></pre>'
nav='<nav class="top"><a class="brand" href="/report.html">attio / исследование</a><a href="/">Локальный клон ↗</a><a href="/report.html">Разбор</a><a href="/gallery.html">64 снимка</a><a href="/code/">Механика</a><a href="/readme.html">Запуск и код</a></nav>'
def page(title,body):
    return '<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><link rel="stylesheet" href="/analysis.css"></head><body>'+nav+body+'<footer class="foot">Снимок публичной главной страницы Attio от 18 сентября 2026. Источник: <a href="https://attio.com/" target="_blank" rel="noopener">attio.com</a>. Брендинг и оригинальные материалы принадлежат правообладателям.</footer></body></html>'

sections=[]
def add(id,title,body):sections.append((id,title,body))
add('scope','01. Что именно исследовано',f'''<p>Это актуальная главная страница Attio с позиционированием вокруг revenue agents. Исследованы первое открытие, полный вертикальный маршрут, desktop-меню, мобильное меню, автоматические продуктовые сцены, перетаскивание окон, переходы по якорям, кейсы клиентов и режим уменьшенного движения.</p><div class="stats"><div class="stat"><b>64</b><small>снимка оригинала</small></div><div class="stat"><b>{len(assets)}</b><small>локальных ресурсов</small></div><div class="stat"><b>6</b><small>размеров экрана</small></div><div class="stat"><b>41 s</b><small>цикл hero</small></div></div><p>Размеры ниже указаны в <b>CSS px</b>, при desktop viewport 1440 × 1000 и DPR 1, если не обозначено иначе. Скриншоты фиксируют разные моменты живых анимаций. Значения взяты из вычисленных стилей и доступной браузеру JavaScript/CSS-сборки. Общие выводы о композиции — дизайнерская интерпретация.</p><div class="callout">Клон сохраняет публичную клиентскую сборку страницы. Это не исходный React-репозиторий Attio и не работающий CRM-сервис. Дальнейшие страницы и аккаунт открываются на оригинальном сайте; локальные формы не отправляют данные.</div>'''+pic(52))
add('structure','02. Сценарий всей страницы',table(['Этап','Содержание','Роль в истории'],[
('Header + hero','Промо-строка, основная навигация, центральный заголовок, CRM и три спутниковых окна','Сначала обещание продукта, затем демонстрация работы'),
('Логотипы','Спокойная полоса клиентских марок','Социальное подтверждение между hero и длинной демонстрацией'),
('Platform','Пять последовательных сценариев с закреплённым указателем','Показать продукт через задачи revenue-команды'),
('Self-building','Подключение источников и сборка профиля контакта','Снизить ощущение сложности настройки'),
('Universal Context','Тёмный раздел с дугой, сигналами, графом связей и интеграциями','Объяснить общий контекст данных'),
('Developer platform','SDK / API / MCP, техническая графика','Показать расширяемость'),
('Цитата + инфраструктура','Выделение слов при скролле, кривая и числовые показатели','Перевести техническую часть в доверие'),
('Клиенты + Changelog','Переключаемые кейсы, четыре обновления','Доказательства применения и развития'),
('CTA + footer','Тёмный финальный призыв, ссылки по группам','Завершить маршрут и дать альтернативную навигацию')])+ '<p>Главная занимает примерно 18 экранов высотой 1000 px. Это длинная продуктовая история, а не набор одинаковых карточек. Светлые разделы показывают конкретный интерфейс, тёмные объясняют инфраструктуру.</p>')
add('grid','03. Сетка и вертикальный ритм','''<p>Основной desktop-контейнер имеет предельную ширину <b>1440 px</b> с внутренними полями <b>24 px</b>. На viewport 1440 это оставляет 1392 px рабочей ширины. В продуктовых секциях используется сетка на <b>24 колонки</b>: боковая навигация занимает 6, контент — 18. Измеренная ширина левой колонки — 347.5 px; тонкие границы входят в расчёт.</p><p>Отдельные текстовые блоки выровнены по внутренним колонкам: например, заголовок Platform начинается около x = 83 px, а описания сценариев — около x = 430 px. Это создаёт вложенную иерархию без множества отдельных подложек.</p><p>Ритм построен на кратных 4 px: 6, 8, 12, 16, 24, 32 px внутри элементов; 64–128 px между крупными частями. В коде есть отдельные пустые desktop-полосы высотой 128 px. Разделители 1 px проходят через весь контейнер и связывают блоки в единую архитектуру.</p><p>Важно: в CSS присутствуют стандартные container-правила, которые ниже переопределяются. Для воспроизведения нужно учитывать итоговый cascade, а не первое найденное правило.</p>'''+ref(1820,'Сетка Platform и sticky-навигация'))
add('type','04. Типографика',table(['Элемент','Шрифт / вес','Размер / интерлиньяж','Трекинг'],[
('Hero desktop','Inter Display / 600','69.33 / 65.86 px','−1.653 px'),('Hero mobile 390 px','Inter Display / 600','40 / 38 px','−0.4 px'),('H2 основных секций','Inter Display / 500','40 / 44 px','−0.4 px'),('H2 mobile','Inter Display / 500','32 / 36 px','−0.32 px'),('Universal Context desktop','Inter Display / 600','96 / 96 px','−2.304 px'),('Описание hero','Inter / 500','18 / 23.4 px','−0.18 px'),('Описание hero mobile','Inter / 500','15 / 19.5 px','−0.17 px'),('Заголовки сценариев','Inter Display / 500','24 / 27.6 px','−0.24 px'),('Текст кнопок','Inter / 500','14 / 20 px','−0.07 px'),('Навигация header','Inter / 500','15 px','из токенов навигации'),('Цитата','Tiempos Text, serif','desktop 48 / 52 px','контраст с интерфейсной типографикой'),('Терминал / технические вставки','JetBrains Mono','локальные размеры 10–14 px','моноширинный ритм')])+'''<p>Заголовок hero зависит от <b>высоты</b> окна браузера. На 1440 × 900 он будет 64 px, а на 1920 × 1080 — около 73.60 px. Переносы дополнительно управляются <code>text-wrap: balance</code>. Для гротесков включена OpenType-функция <code>ss03</code>.</p>'''+code('font-size: clamp(64px, calc(16px + 5.333svh), 80px);\nline-height: .95;\nletter-spacing: clamp(-2.4px, calc(2.08px - .3733svh), -1.28px);')+ref(915,'Адаптивная типографика hero'))
palette=[('#ffffff','Основной фон'),('#fafafb','Вторичный фон'),('#f3f4f6','Поверхность'),('#e4e7ec','Тонкая граница'),('#1c1d1f','Основной текст'),('#6f7988','Пояснения'),('#266df0','Синий акцент'),('#101010','Тёмная секция')]
add('palette','05. Цвет, границы и поверхности','<div class="swatches">'+''.join(f'<div class="swatch"><i style="--sw:{c}"></i><span>{n}<br><code>{c}</code></span></div>' for c,n in palette)+'</div>'+'''<p>Основная палитра почти нейтральная: сине-серые подписи и границы поддерживают холодное ощущение интерфейса. Яркий синий используется точечно для действий, выбранного состояния и анимации данных. В современных браузерах часть цветов вычисляется через Lab / Oklab; HEX выше — значения из базовых CSS-токенов.</p><p>У тёмной области собственные семантические переменные: фон #101010, светлый текст и более тёмные границы. Это переключение токенов внутри <code>.dark</code>, а не фильтр инверсии всей страницы.</p>''')
add('header','06. Header и раскрывающиеся меню','''<p>Промо-строка высотой <b>48 px</b> расположена над навигацией. Высота самой навигации — <b>68 px desktop</b> и <b>52 px mobile</b>; суммарно 116 и 100 px. После закрытия промо высота пересчитывается через CSS-переменные, которыми пользуются sticky-элементы ниже.</p><p>Слой header имеет z-index 92, мегаменю — 93. Светлый фон header полупрозрачный, с <code>backdrop-filter</code> на отдельном внутреннем слое. При прохождении тёмных секций шапка меняет тему. Переход цвета занимает 250 ms.</p><p>Platform раскрывается в широкое меню: группы продукта слева и отдельная колонка быстрых ссылок справа. На 1440 px измеренный popup — <b>912 × 478 px</b>, x = 163, y = 106. Resources компактнее. Мобильная версия использует отдельный dialog с вложенными уровнями.</p>'''+table(['Контрол','Геометрия','Поведение'],[('Start for free','≈110.45 × 36 px, radius 10 px, padding-x 12 px','Тёмная кнопка'),('Sign in','Высота 36 px, radius 10 px','Светлая outline-кнопка'),('Закрыть промо','32 × 32 px; SVG 18 × 18 px','Убирает промо-полосу'),('Мобильное меню','36 × 36 px; SVG 24 × 24 px','Открывает dialog'),('Hover кнопок','Базовый переход 300 ms, hover/active 50 ms','Быстрый отклик, более мягкое возвращение')])+pic(3)+pic(35,'Мобильное меню оригинала'))
add('hero-layout','07. Размеры hero и интерфейсного окна',table(['Объект','Положение / размер при 1440 × 1000'],[('Badge над заголовком','Верх ≈216 px; высота 30 px'),('Заголовок','x ≈287.78; y = 282; ширина ≈864.42; высота ≈65.86 px'),('Описание','y ≈383.86; ширина 486; высота ≈46.78 px'),('CTA','y ≈454.64; высота 36 px'),('Главное окно CRM','x = 180; y ≈619.13; ширина 1080; высота ≈619.03 px'),('Внутренний экран CRM','Высота min(40.35vw, 775px); ≈581 px на 1440 px'),('Верхняя рамка окна','32 px desktop; 16 px mobile'),('Внешний / внутренний радиус','16 / 12 px desktop'),('Внутренние поля рамки','6 px по бокам и снизу'),('Окно звонка','272 px максимум по ширине'),('Slack','268 px максимум по ширине'),('Терминал','300 px максимум по ширине')])+'''<p>Главное окно занимает 75% viewport на desktop и имеет max-width 1440 px. На промежуточной ширине используется 2/3. Это независимая от основного контентного контейнера композиция. Видимые координаты меняются при скролле, ресайзе и перетаскивании.</p><p>Между badge и заголовком — 36 px. Между нижней границей заголовка и описанием — около 36 px, между описанием и CTA — 24 px. От CTA до окна в измеренном состоянии — около 128 px. Последний промежуток вычисляется адаптивно и не является постоянным margin.</p>'''+ref(915,'Полная desktop-композиция hero'))
add('entrance','08. Первое появление',table(['Слой','Задержка','Длительность','Свойства'],[('Badge','0 ms','600 ms','opacity 0 → 1, blur 1.5 → 0'),('H1','100 ms','600 ms','opacity + blur'),('Описание','200 ms','600 ms','opacity + blur'),('Первый CTA','300 ms','600 ms','opacity + blur'),('Второй CTA','400 ms','600 ms','opacity + blur'),('Главное окно','450 ms','900 ms','opacity 0 → 1, scale .98 → 1'),('Мобильный экран CRM','400 ms','750 ms','opacity 0 → 1')])+'''<p>Используется <code>cubic-bezier(0, 0, .58, 1)</code>: мягкое проявление без заметного пружинящего отскока. Здесь нет полноэкранного процентного прелоадера. Пустой первый кадр возможен до гидратации и начала анимаций; это не отдельная загрузочная сцена.</p><p>В глобальном наборе motion-параметров существуют entrance 800 ms, reveal 600 ms, exit 300 ms, switch 500 ms. Часть внутренних сцен дополнительно применяет <code>withTempo(value) = value × 0.85</code>; поэтому, например, 800 ms превращаются в 680 ms. Не все эффекты используют этот множитель.</p>'''+ref(17,'Общие motion-токены')+ref(544,'Появление окна')+ref(915,'Stagger текста'))
add('hero-motion','09. Скролл, окна и 41-секундный цикл','''<p>На desktop уже при <b>scrollY ≥ 8 px</b> заголовочная группа начинает скрываться: opacity → 0, blur → 2.5 px за 500 ms. Одновременно проявляются дополнительные окна с blur 3 → 0 за 600 ms. Порядок: терминал, Slack, звонок, с шагом задержки 200 ms.</p><p>Главное окно немного уменьшается. Пружина имеет <code>stiffness:120, damping:26, mass:1</code>. На 1440 × 1000 исходная ширина 1080 px стабилизируется примерно на 1026 px, то есть scale 0.95. На низких экранах есть дополнительное ограничение, учитывающее высоту окна.</p><p>После прогресса hero ≥ 0.1 окна становятся интерактивными. Pointer Capture удерживает drag, координаты ограничиваются контейнером. Активное окно поднимается выше остальных. Это настоящие перемещаемые DOM-элементы. При drag тень становится глубже; переход тени — 220 ms.</p>'''+table(['Сцена центрального CRM','Время'],[('Ask Attio','11 s'),('Data model','6.5 s'),('Workflows','17 s'),('Reporting','6.5 s'),('Полный повтор','41 s')])+'''<p>Демонстрационные данные заранее заданы в коде. AI здесь не делает реальные запросы. Боковой Slack меняет диалог раз в 5 s, терминал — раз в 9 s. Эффект печати терминала использует интервалы 26 ms/символ, а команды — 18 ms/символ. В окне звонка отдельно присутствует небольшое loop-video и прокрутка транскрипта: вся hero-сцена не является одним видео.</p>'''+pic(50)+ref(619,'Порядок и продолжительность сцен')+ref(646,'Drag с ограничениями')+ref(846,'Реакция на скролл'))
add('effects','10. Градиенты, свечение и тени','''<p>Фон hero состоит из холодного радиального градиента, вертикальных штрихов и большой белой радиальной маски сверху. Штрихи — повторение 1 px каждые 8 px с opacity 0.4. При прокрутке изменяются прозрачность нижнего свечения и масштаб маски. Поэтому фон кажется пространственным, хотя основной эффект сделан CSS-слоями.</p>'''+code('background-image: radial-gradient(\n  90% 80% at 50% 100%,\n  #e6ecff 0%, #bccbff 45%, #86a0ee 100%\n);\n\n/* Пять мягких уровней дают глубину без тяжёлой тёмной тени */\nbox-shadow:\n  0 0 0 1px rgba(11,13,24,.06),\n  0 1px 2px rgba(11,13,24,.025),\n  0 3px 6px rgba(11,13,24,.03),\n  0 8px 14px rgba(11,13,24,.035),\n  0 16px 28px rgba(11,13,24,.04);')+'''<p>Окна имеют полупрозрачные поверхности и backdrop blur. Во время скролла blur фона временно выключается, а подложка становится непрозрачной. Состояние «идёт скролл» сбрасывается через 160 ms после последнего события; на смену режима предусмотрено отдельное окно 1300 ms. Это конкретная оптимизация отрисовки.</p>'''+ref(527,'Радиальный фон и полосы')+ref(645,'Тени')+ref(902,'Ограничение тяжёлых эффектов во время скролла'))
add('scroll','11. Почему прокрутка ощущается плавной','''<p>В исследованной сборке не обнаружена Lenis или GSAP ScrollTrigger для управления всей страницей. <b>Основной скролл — нативный.</b> Вокруг него работают CSS sticky, пассивные scroll-listeners, requestAnimationFrame, Motion values и отдельные пружины.</p><p>По клику на сценарий вызывается браузерный <code>scrollIntoView({ behavior: "smooth", block: "start" })</code>. Отступ сверху берётся из <code>scroll-margin-top</code>, чтобы header не перекрывал секцию. Активный пункт выбирается относительно линии на 45% высоты viewport. Во время программного перехода scroll-spy временно приостановлен до <code>scrollend</code>, с резервным таймером 1500 ms.</p><p>Проверка перехода к Forecast revenue дала одинаковую конечную позицию оригинала и клона: scrollY = 5656, верх секции ≈116 px — ровно под шапкой. Длительность плавного перехода зависит от браузера и расстояния; приписывать ей постоянные 800 ms было бы неверно.</p>'''+code('const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;\nsection.scrollIntoView({\n  behavior: reduce ? "auto" : "smooth",\n  block: "start"\n});')+ref(1784,'Переходы и scroll-spy')+'<p><a href="/source/navigation-samples.json">Покадровые измерения перехода</a> · <a href="/source/scroll-samples.json">Измерения hero при прокрутке</a></p>')
add('platform','12. Пять продуктовых сценариев','''<p>Левая навигация закрепляется под header; высота её области равна viewport минус шапка. Справа последовательно идут пять больших демонстраций, а не одна подменяемая панель. На mobile навигация становится горизонтальной лентой с автоматическим подводом выбранного пункта и градиентными краями.</p>'''+table(['Сценарий','Визуальная механика'],[('Build pipeline','Таблица компаний, появление enrichment-данных, ввод запроса и список найденных аккаунтов. Отдельные результаты проявляются со stagger.'),('Convert leads','SVG-связи и последовательное прохождение узлов workflow. Маски и статусы показывают направление процесса.'),('Run sales motions','Kanban-колонки, движение карточек и компактные сопутствующие интерфейсы. Часть сцен запускается при попадании в видимую область.'),('Forecast revenue','Печать SQL, появление аналитического ответа, столбцы графика через анимированный clipPath.'),('Retain and expand','Данные здоровья аккаунта, подсказки и действия агента. Используются fade, blur и небольшие смещения.')])+'''<p>Крупный визуальный фрейм имеет отношение сторон <code>1044 / 654</code>. На desktop внутри рисуется сцена 1044 × 654; на меньшем экране используется база 522 × 327. Затем сцена масштабируется относительно ширины контейнера. Это сохраняет композицию интерфейса, вместо попытки сделать каждую мини-таблицу самостоятельным адаптивным приложением.</p><p>Типичный вход карточки: y = 16 → 0, blur = 2.5 → 0, opacity = 0 → 1. Для ряда эффектов threshold видимости — 0.4, часть запускается один раз. Это не универсальный параметр для всех блоков.</p>'''+pic(54)+pic(56)+ref(1752,'Масштабирование продуктовых фреймов')+ref(1502,'Столбцы через SVG clipPath'))
add('self-building','13. Self-building: данные собираются сами','''<p>После насыщенной продуктовой части появляется симметричный заголовок и большая карточка контакта. Смысл анимации — показать последовательное заполнение профиля данными из разных источников: компания, активности, контакты, социальные связи.</p><p>Для появляющихся полей используется общий wrapper: fade + blur, задержка начинается с 180 ms и увеличивается шагами по 40 ms. На уровне карточек есть тонкие границы, практически белые подложки и очень слабые цветные акценты. Над профилем проходят линейные «сигналы», связывающие источники с результатом.</p><p>Макет меняется по ширине; размеры отслеживаются ResizeObserver. Это объясняет, почему горизонтальные линии и центр карточки сохраняют привязку при ресайзе.</p>'''+pic(58)+ref(197,'Появление полей профиля')+ref(495,'Сборка секции Self-building'))
add('universal','14. Universal Context: тёмная сцена','''<p>Главный контраст страницы — переход к почти чёрному фону и огромному заголовку 96 px. Дуга под заголовком собирается из CSS-градиентов и масок. Она не требует 3D-сцены WebGL.</p><p>Цветной обод состоит из conic-gradient и нескольких слоёв: широкий blur 10 px с opacity .45, узкий blur 2 px и внутреннее тёмное заполнение. Белое свечение вокруг задаётся отдельным radial-gradient. Hue и saturation немного колеблются по синусоидальным функциям времени; анимация ограничена видимой областью.</p><p>Появление заголовка и дуги привязано к scroll progress. На текст действуют opacity, небольшое y-смещение и blur, сглаженные пружинами. У заголовка и подписи разные диапазоны прогресса: они не проявляются строго одновременно.</p>'''+pic(59)+ref(1845,'Conic-gradient, маски, свечение')+ref(2330,'Scroll progress и параметры пружин')+'''<p>Далее идут пять коротких тезисов, визуализация связей и ряд интеграций. Иконки интеграций на desktop занимают 96 px, на mobile — 80 px; сами логотипы посажены на тёмные округлённые плитки с очень тонким внутренним бликом.</p>'''+pic(61)+ref(1867,'Плитки интеграций'))
add('developer','15. Developer platform и цитата','''<p>Раздел SDK / API / MCP продолжает тёмную тему: текстовая колонка и линейная техническая графика уравновешивают предыдущие декоративные эффекты. На больших экранах сетка использует 24 колонки; на меньших контент складывается вертикально.</p><p>После него размещена большая serif-цитата. Для неё выделен scroll-контейнер высотой <b>250svh</b>, а сам текст закреплён внутри на высоту viewport минус header. На диапазоне 10–80% прогресса слова последовательно меняют цвет из приглушённого в основной; CSS-переход каждого слова — 500 ms.</p><p>Здесь выразительность создаёт смена шрифта на Tiempos Text и контролируемый темп чтения. Нельзя заменить этот участок обычным fade всей строки и получить то же ощущение.</p>'''+pic(62)+pic(19,'Цитата с последовательным выделением слов')+ref(52,'Developer platform')+ref(1831,'Scroll-driven выделение слов'))
add('proof','16. Инфраструктура и кейсы','''<p>Инфраструктурный блок возвращает светлый фон. Большая возрастающая кривая и счётчики показывают масштаб. Векторная кривая вычисляется из 121 точки и степени 2.4; линия использует <code>vector-effect: non-scaling-stroke</code>, чтобы толщина не расползалась при масштабировании.</p><p>Кейсы клиентов — отдельный четырёхпозиционный переключатель. Автопереход происходит раз в <b>6 секунд</b>, только когда блок видим и вкладка браузера активна. Hover и focus ставят воспроизведение на паузу; ручной выбор отключает автоматический ход.</p><p>Смена кейса: выход 300 ms, вход 500 ms. Текст немного сдвигается на 12 px по направлению переключения; изображение — на 5 px и scale 1.015 → 1. Изображение по умолчанию имеет насыщенность .55, на hover приходит к 1; масштаб на hover — 1.005.</p>'''+pic(63)+ref(928,'Геометрия инфраструктурной кривой')+ref(65,'Автопрокрутка и переходы кейсов'))
add('ending','17. Changelog, финальный CTA и footer','''<p>Changelog представлен четырьмя карточками в ряд на desktop: дата, тип обновления, короткий заголовок и превью. Тонкие линии делают карточки частью общей сетки; интервалы и невысокая плотность текста важнее крупных декоративных рамок.</p><p>Финальный CTA снова использует тёмную тему. Заголовок заметно меньше Universal Context: на desktop примерно 56 px с интерлиньяжем 56 px и ограничением ширины 672 px. Под ним повторяется путь к началу работы или разговору с sales.</p><p>Footer организован по группам платформы, компании, импорта, приложений и ресурсов. На мобильном экране структура вытягивается по вертикали, а многочисленные ссылки остаются частью длинной страницы. Это сохранено в локальном клоне.</p>'''+pic(64)+pic(24,'Финальный CTA и footer'))
add('responsive','18. Адаптивность',table(['Viewport','H1','Header с промо','Переполнение страницы'],[(f'{x["width"]} × {x["height"]}',f'{float(x["headingSize"].replace("px","")):.2f} px',f'{x["headerHeight"]} px','нет' if x['width']==x['scrollWidth'] else 'есть') for x in qa['responsive']])+'''<p>Два важных порога: <b>768 px</b> переключает mobile/desktop-композицию hero, <b>992 px</b> переключает основную навигацию и многие продуктовые макеты. Не все блоки используют одинаковые breakpoints: например, Universal Context дополнительно измеряет 1024 и 1280 px.</p><p>На 390 px: боковые поля текста hero 24 px, заголовок занимает две строки, описание — две строки. Форма имеет ширину 320 px, поле и кнопка — по 40 px высотой. Демонстрационный экран ниже имеет фиксированную внутреннюю высоту 296 px и обрезается по контейнеру. Вспомогательные плавающие окна desktop здесь не показываются.</p><p>Переход к форме вместо desktop-кнопки — часть оригинального поведения, а не добавленная в клоне UX-правка.</p>'''+pic(34))
add('accessibility','19. Доступность и производительность','''<p>В оригинале есть семантические кнопки, подписанный mobile-dialog, focus-visible, aria-expanded у меню, aria-current у навигации, aria-pressed у клиентских переключателей и aria-live для смены кейса. Декоративные интерфейсы часто помечены aria-hidden.</p><p><b>Reduced motion поддерживается частично.</b> MotionConfig и отдельные helpers сокращают движение, многие CSS-анимации используют motion-safe / motion-reduce. Однако проверка с <code>prefers-reduced-motion: reduce</code> показала, что центральный hero продолжает менять табы: Ask Attio → Data model. В клоне это поведение оригинала сохранено. Это не заявление о полном соответствии WCAG.</p><p>Часть контролов имеет высоту 36 px, а некоторые декоративные интерфейсные элементы очень мелкие. Эти мини-интерфейсы предназначены для демонстрации, а не для реальной работы с CRM. Полный аудит контраста и assistive technologies в задачу не входил.</p><p>Оптимизации: viewport-gating сцен, пассивные слушатели, обработка скролла через requestAnimationFrame, ResizeObserver, локальные WOFF2, SVG вместо больших растровых слоёв, отключение backdrop blur во время движения. FPS, Core Web Vitals и поведение на физических телефонах не измерялись.</p>'''+ref(918,'MotionConfig')+ref(66,'Reduced motion и видимость кейсов')+'<p><a href="/source/qa.json">Результаты браузерных проверок</a></p>')
add('clone','20. Что входит в локальный клон','''<p>Сохранены HTML, публичные JS/CSS-чанки, шрифты, картинки, SVG и видеофрагмент звонка. Сборка Next.js / Turbopack гидратируется локально, поэтому работают исходные React/Motion-компоненты: анимации, меню, drag, переключатели и responsive-ветки.</p>'''+table(['Работает локально','Граница реализации'],[('Полная главная страница','Все исследованные секции и footer'),('Hero','Оригинальные демонстрационные сцены и перетаскиваемые окна'),('Меню и якоря','Раскрытие, mobile-dialog, переходы между секциями'),('Кейсы','Автопереход, ручной выбор, hover/focus'),('Шрифты и медиа','Локальные файлы; запросы Next Image обслуживаются сохранёнными файлами'),('Формы','Поля и интерфейс доступны; вместо отправки открывается сообщение о локальном демо'),('Ссылки на другие страницы','Открывают официальный сайт в отдельной вкладке'),('CRM / авторизация / backend','Не реализованы'),('Аналитика и tracking','Не отправляются; внешние загрузки ограничены CSP')])+'''<p>В контрольной загрузке и проходе по странице: <b>0 JavaScript-ошибок, 0 HTTP-ошибок ресурсов, 0 внешних запросов, 0 видимых сломанных изображений</b>. Проверены шесть viewport, mobile-меню, форма и переключение кейса. Drag дал ожидаемое перемещение на 70 px по X и 30 px по Y. Якорь совпал с оригиналом по конечному положению.</p><p>Это точный по структуре публичный snapshot, а не гарантия попиксельного совпадения каждого кадра: таймеры, браузерное сглаживание и высота viewport влияют на текущую фазу.</p>''')
add('code','21. Где смотреть и как переносить код',table(['Файл / модуль','Что внутри'],[('<a href="/source-view.html?file=0y14chldcipxr.js&line=17">Главный homepage bundle</a>','Motion-токены, hero, Platform, Self-building, Universal Context, кейсы'),('<a href="/source-view.html?file=3nrb1gxh-42c7.css&line=1">Основной CSS</a>','Шрифты, semantic colors, сетка, responsive utilities, размеры и состояния'),('<a href="/code/motion-tokens.js">code/motion-tokens.js</a>','Читаемые параметры эффектов и длительности циклов'),('<a href="/code/design-tokens.css">code/design-tokens.css</a>','Выделенный набор размеров, цветов и теней'),('<a href="/code/reveal.js">code/reveal.js</a>','Авторская компактная адаптация reveal и smooth anchor без фреймворка'),('<a href="/source/hero-details.json">hero-details.json</a>','Вычисленные стили и геометрия hero'),('<a href="/source/asset-map.json">asset-map.json</a>','Оригинальный URL → локальный путь, MIME и размер'),('<a href="/readme.html">Инструкция</a>','Запуск, структура ZIP, различия между snapshot и адаптацией')])+'''<p>Для переноса в свой проект разумнее брать отдельные принципы и токены: небольшие blur, несколько уровней тени, ограниченные translate, нативный скролл и разные responsive-композиции. Целиком минифицированный сайт неудобно превращать в поддерживаемый исходный проект; он сохранён здесь прежде всего для точного локального воспроизведения и изучения.</p><p><a href="/code/">Открыть изолированное демо появления →</a></p>''')

toc='<aside class="toc">'+''.join(f'<a href="#{id}">{title}</a>' for id,title,_ in sections)+'</aside>'
body='<header class="cover"><div class="eyebrow">Attio.com / 18.09.2026 / desktop + mobile</div><h1>Как устроен лендинг Attio.</h1><p>Сетка, типографика, глубина интерфейса и движение — с измерениями, кодом и рабочим локальным клоном.</p><div class="pills"><a class="pill" href="/">Открыть клон ↗</a><a class="pill" href="/gallery.html">64 состояния оригинала</a><a class="pill" href="/readme.html">Запуск и ZIP</a></div></header><main class="layout">'+toc+'<div class="content">'+''.join(f'<section id="{id}"><h2>{title}</h2>{text}</section>' for id,title,text in sections)+'</div></main>'
(D/'report.html').write_text(page('Attio — полный разбор лендинга',body))

cards=[]
for i,x in enumerate(gallery):
    label=x['label'] if i!=1 else 'Переходный кадр после закрытия cookie-панели'
    group='mobile' if x['viewport']['width']<768 else 'desktop'
    cats=group+(' hero' if 'hero' in x['file'] else '')+(' menu' if 'menu' in x['file'] else '')
    cards.append(f'<figure data-category="{cats}"><a href="/{x["file"]}"><img loading="lazy" src="/{x["file"]}" alt="{html.escape(label)}"></a><figcaption><b>{i+1:02}. {html.escape(label)}</b><br>{x["viewport"]["width"]} × {x["viewport"]["height"]} · scrollY {round(x["scrollY"])} px</figcaption></figure>')
filters='<div class="filters">'+''.join(f'<button data-filter="{key}" aria-pressed="{str(key=="all").lower()}">{label}</button>' for key,label in [('all','Все'),('desktop','Desktop'),('mobile','Mobile'),('hero','Hero'),('menu','Меню')])+'</div>'
js='<script>document.querySelectorAll("[data-filter]").forEach(b=>b.onclick=()=>{document.querySelectorAll("[data-filter]").forEach(x=>x.setAttribute("aria-pressed",String(x===b)));document.querySelectorAll("[data-category]").forEach(f=>f.hidden=b.dataset.filter!=="all"&&!f.dataset.category.split(" ").includes(b.dataset.filter))});</script>'
(D/'gallery.html').write_text(page('Attio — 64 снимка оригинала','<header class="cover"><div class="eyebrow">Визуальные доказательства</div><h1>64 состояния страницы.</h1><p>Все кадры в этой галерее сняты с оригинального attio.com. Нажмите на изображение, чтобы открыть его в полном размере. Часть кадров намеренно фиксирует переходные состояния.</p></header>'+filters+'<main class="gallery">'+''.join(cards)+'</main>'+js))

readme='''<header class="cover"><div class="eyebrow">Локальный запуск · Python 3.10+</div><h1>Клон, исходные ресурсы<br>и код подключения.</h1><p>Никаких npm install, ключей API или production backend для просмотра не требуется.</p><div class="pills"><a class="pill" href="/download.zip">Скачать ZIP</a><a class="pill" href="/">Открыть клон</a></div></header><main class="prose"><h2>Запуск после распаковки</h2>'''+code('cd attio-landing-analysis\npython3 serve.py --port 8772')+'''<p>Откройте <a href="http://127.0.0.1:8772/">http://127.0.0.1:8772/</a>. Если порт занят, передайте другой. Важно использовать <code>serve.py</code>, а не file://: сервер разрешает сохранённые Next Image URL с параметрами и выставляет правильные MIME-типы.</p><h2>Содержимое</h2>'''+table(['Путь','Назначение'],[('dist/index.html','Готовый локальный клон главной'),('dist/_next/','Локализованная публичная сборка Next.js'),('dist/mirror/','Иконки и материалы Storyblok'),('dist/videos/','Видео и poster окна звонка'),('dist/report.html','Подробный анализ'),('dist/gallery.html + evidence/','64 снимка оригинала'),('dist/code/','Изолированная адаптация motion и design tokens'),('dist/local-preview.js','Локальный transport-адаптер, обработка форм и ссылок'),('source/index.html','Оригинальный HTML-ответ'),('source/raw/','Нетронутые JS/CSS-ресурсы'),('source/reference/','Форматированные читаемые версии JS/CSS'),('source/*.json','Измерения, карты ресурсов, результаты проверки'),('scripts/','Пересборка snapshot, отчёта, проверка ресурсов и упаковка')])+'''<h2>Подключение отдельного появления</h2>'''+code('<link rel="stylesheet" href="./code/design-tokens.css">\n<div data-reveal data-delay="80">Карточка</div>\n<script type="module">\n  import { reveal } from "./code/reveal.js";\n  const cleanup = reveal(document);\n</script>')+'''<p><a href="/code/">Рабочее демо</a>. Адаптация использует IntersectionObserver и Web Animations API. Она не заменяет React/Motion-сцены полного клона.</p><h2>Пересборка и проверка</h2>'''+code('python3 scripts/build.py\npython3 scripts/build-report.py\npython3 scripts/verify.py --port 8772\npython3 scripts/package.py')+'''<p><code>build.py</code> восстанавливает HTML и локализованные чанки из сохранённых оригиналов. Правки дизайна полного snapshot лучше хранить отдельно: прямые изменения dist/_next будут перезаписаны. Форматированные source/reference уже включены; format-reference.cjs нужен только при повторном форматировании с установленным esbuild.</p><h2>Границы клона</h2><p>Это главная страница, а не все маршруты сайта и не CRM-приложение. Продуктовые подстраницы, pricing, аккаунт и внешние ресурсы открываются на официальном домене. Внутренние якоря и переключатели работают локально. Отправка формы перехватывается сообщением «Локальное демо»; данные не сохраняются и заявка не создаётся.</p><p>Клиентская сборка сохранена из публично загружаемых ресурсов. Исходный репозиторий Attio не получен. Оригинальные бренды, тексты, шрифты и графика не выдаются за авторский дизайн.</p></main>'''
(D/'readme.html').write_text(page('Attio — запуск и код подключения',readme))

motionbody='''<header class="cover"><div class="eyebrow">Адаптация параметров оригинала</div><h1>Маленькое движение.<br>Большая разница.</h1><p>Изолированный пример opacity + translateY + blur. Полный интерфейс работает на главной странице клона.</p><button id="replay">Повторить появление</button></header><main class="prose"><div class="pairs"><article data-reveal class="stat"><span class="eyebrow">01 / REVEAL</span><h2>16 px → 0</h2><p>Вертикальное смещение с плавным торможением.</p></article><article data-reveal data-delay="80" class="stat"><span class="eyebrow">02 / FOCUS</span><h2>2.5 px → 0</h2><p>Лёгкое размытие исчезает одновременно с проявлением.</p></article></div><h2 style="margin-top:50px">Подключение без фреймворка</h2>'''+code('import { reveal } from "./code/reveal.js";\nconst cleanup = reveal(document);')+'''<p>Здесь duration = 800 × 0.85 = 680 ms. Это учебная реализация на Web Animations API; оригинал использует React и Motion. Reduced motion отключает движение в этом примере.</p><p><a href="/code/motion-tokens.js">Motion tokens</a> · <a href="/code/design-tokens.css">CSS tokens</a> · <a href="/code/reveal.js">Reveal / smooth anchor</a></p></main><script type="module">import{reveal}from'/code/reveal.js';let stop=reveal();document.querySelector('#replay').onclick=()=>{stop();document.querySelectorAll('[data-reveal]').forEach(e=>e.getAnimations().forEach(a=>a.cancel()));stop=reveal()};</script>'''
(D/'code/index.html').write_text(page('Attio — изолированное motion-демо',motionbody))

viewer='''<main class="prose" style="max-width:1400px"><h1 id="title">Код оригинала</h1><p>Форматированная версия публичного production-файла. Имена переменных могут оставаться минифицированными.</p><pre id="source" style="max-height:none"></pre></main><script>const p=new URLSearchParams(location.search),f=p.get('file')||'0y14chldcipxr.js',line=Number(p.get('line')||1);if(/^[a-zA-Z0-9_.-]+\\.(js|css)$/.test(f)){document.querySelector('#title').textContent=f;fetch('/source/reference/'+f).then(r=>r.text()).then(t=>{const root=document.querySelector('#source');t.split('\\n').forEach((s,i)=>{let e=document.createElement('span');e.id='L'+(i+1);e.style.display='block';e.textContent=String(i+1).padStart(5,' ')+'  '+s;if(i+1===line)e.style.background='#344368';root.append(e)});document.getElementById('L'+line)?.scrollIntoView({block:'center'})})}</script>'''
(D/'source-view.html').write_text(page('Attio — просмотр публичного кода',viewer))
